// Frontend dataset contract. Generated by scripts/build-frontend-data.ts from the backend
// datasets in data/<campus>/ and served from public/data/. Keep in sync with the generator.
import type { Rule } from '../domain/types'

export type CampusId = 'UTM' | 'UTSG' | 'UTSC'
export type CampusStatus = 'available' | 'planned'

export interface CampusEntry {
  id: CampusId
  name: string
  shortName: string
  status: CampusStatus
  calendarUrl: string
  /** Present only for available campuses; relative to public/data/. */
  dataPath?: string
  academicYear?: string
  courseCount?: number
  programCount?: number
  /** Subjects shown first on a first visit (UTM: CSC, MAT, STA, ECO, PSY, BIO). */
  startSubjects?: string[]
}

export interface CampusRegistry {
  schemaVersion: 1
  generatedAt: string
  campuses: CampusEntry[]
}

export interface Division {
  id: string
  label: string
}

export interface SubjectInfo {
  code: string
  name: string
  department: string
  division: string
  courseCount: number
}

/** One requirement field of a course: official text, parsed rule and every referenced id. */
export interface RequirementLite {
  /** Official wording (whitespace-normalised). */
  text: string
  rule: Rule
  /** Referenced course ids, including other campuses (`UTSG:CSC148H1`). These are graph edges. */
  ids: string[]
  /** Codes mentioned but ruled out / advisory / conditional; shown in details, never edges. */
  mentioned?: string[]
  /** Same-campus codes that are not in this calendar (retired or misprinted); never edges or counts. */
  unresolved?: string[]
}

export interface GraphCourse {
  id: string
  code: string
  title: string
  subject: string
  level: number
  credits: number
  distribution?: string
  /** Delivery location when not the main campus (e.g. "Sheridan"). */
  deliveryCampus?: string
  /** Each requirement is omitted when the calendar field is empty. */
  prereq?: RequirementLite
  coreq?: RequirementLite
  exclusion?: RequirementLite
  recommended?: RequirementLite
  restriction?: RequirementLite
  notes?: string
}

export interface GraphDataset {
  schemaVersion: 1
  campus: CampusId
  academicYear: string
  /** When the official pages were fetched. */
  fetchedAt: string
  /** Deterministic build stamp: equals fetchedAt so unchanged data regenerates byte-identically. */
  generatedAt: string
  sources: {
    calendar: string
    courseSearch: string
    programSearch: string
    /** `{slug}` is the lower-case course code, e.g. csc148h5. */
    coursePageTemplate: string
    programPageTemplate: string
  }
  divisions: Division[]
  subjects: SubjectInfo[]
  /** Sorted by id. */
  courses: GraphCourse[]
}

export interface DetailsDataset {
  schemaVersion: 1
  campus: CampusId
  /** course id → official description. */
  descriptions: Record<string, string>
}

export interface ProgramGroupLite {
  id: string
  label: string
  category: 'admission' | 'completion'
  text: string
  rule: Rule
  ids: string[]
  /** Codes the group text rules out or only mentions ("except CSC392H5"); never highlighted. */
  mentioned?: string[]
  /** Same-campus codes absent from this calendar. */
  unresolved?: string[]
}

export interface ProgramLite {
  id: string
  code: string
  title: string
  /** Official type: Specialist, Major, Minor, Certificate, Focus, ... */
  type: string
  /** 'url-slug' when the calendar gives no POSt code and `code` is the page slug (do not show it as a code). */
  codeSource?: 'url-slug'
  sourceUrl: string
  description: string
  notes?: string
  admissionText: string
  completionText: string
  groups: ProgramGroupLite[]
}

export interface ProgramsDataset {
  schemaVersion: 1
  campus: CampusId
  programs: ProgramLite[]
}
